implements(Key) :-
    citation(Key, _).

test(the_gate_key_is_recorded) :-
    implements(eu_reg_2022_2554_art_16_1).
test(the_fixed_four_are_recorded) :-
    implements(eu_reg_2024_1774_art_1),
    implements(eu_reg_2024_1774_art_2_1),
    implements(eu_reg_2024_1774_art_2_2),
    implements(eu_reg_2024_1774_art_3).
test(the_second_run_keys_are_recorded) :-
    implements(eu_reg_2024_1774_art_3_a_run2),
    implements(eu_reg_2024_1774_art_3_b_run2),
    implements(eu_reg_2024_1774_art_3_c_run2).
test(twenty_nine_keys_are_recorded) :-
    findall(Key, citation(Key, _), Keys),
    sort(Keys, DistinctKeys),
    length(DistinctKeys, 29).

test(a_shortened_key_is_not_recorded, fail) :-
    implements(art_3_a_run2).
